function filterChips(values,selected,action){return `<div class="filter-row" data-seg="${esc(action)}"><span class="seg-ind" aria-hidden="true"></span><md-chip-set>${values.map(([value,label])=>`<md-filter-chip label="${esc(label)}" ${selected===value?'selected':''} data-action="${action}" data-value="${esc(value)}" aria-label="Filtrar por ${esc(label)}"></md-filter-chip>`).join('')}</md-chip-set></div>`;}
function renderCatalog(){
 const list=filteredItems();return `<div class="page-head"><div><h1>${catalogFilter==='imovel'?'Imóveis':catalogFilter==='desapego'?'Desapegos':'Desapegos e imóveis'}</h1><p>${list.length} ${list.length===1?'oportunidade':'oportunidades'} em ${esc(state.city)}</p></div>${!readonly()?btn('Anunciar','create','','tonal','add'):''}</div>${readonlyHtml()}${filterChips([['all','Tudo'],['desapego','Desapegos'],['imovel','Imóveis']],catalogFilter,'catalog-filter')}${catalogFilterFields()}<div id="catalog-results">${itemResults(list)}</div>`;
}
function catalogFilterFields(){return `<div class="filter-panel">${selectField('catalog-hood','Bairro',['Todos',...HOODS],searchHood)}${selectField('catalog-sort','Ordenar',[['recent','Mais recentes'],['price-low','Menor preço'],['price-high','Maior preço']],searchSort)}${catalogPriceSlider()}</div>`;}
// Faixa de preço (Rodada 10): md-slider de intervalo; o máximo fica acima do maior preço para que o extremo exclua todos.
function catalogPriceRange(){const prices=cityItems().filter(x=>catalogFilter==='all'||x.kind===catalogFilter).map(x=>x.numPrice||0);const top=Math.max(0,...prices);const step=top>5000?100:top>500?50:10;return {max:Math.ceil((top+1)/step)*step,step};}
function catalogPriceLabel(a,b,max){return a<=0&&b>=max?'Qualquer preço':`${money(a)} a ${money(b)}`;}
function catalogPriceSlider(){const {max,step}=catalogPriceRange();const a=Math.min(Number(searchMin)||0,max),b=Math.min(Number(searchMax)||max,max);searchMin=a>0?String(a):'';searchMax=b<max?String(b):'';return `<div class="price-filter"><div class="row between"><span class="small">Preço</span><span class="small muted" id="catalog-price-label" aria-live="polite">${catalogPriceLabel(a,b,max)}</span></div><md-slider id="catalog-price" range labeled min="0" max="${max}" step="${step}" value-start="${a}" value-end="${b}" aria-label-start="Preço mínimo" aria-label-end="Preço máximo" style="width:100%"></md-slider></div>`;}
function filteredItems(){let list=cityItems().filter(x=>x.status==='active'&&(catalogFilter==='all'||x.kind===catalogFilter)&&(searchHood==='Todos'||x.hood===searchHood)&&(!searchMin||x.numPrice>=Number(searchMin))&&(!searchMax||x.numPrice<=Number(searchMax)));return list.sort((a,b)=>searchSort==='price-low'?a.numPrice-b.numPrice:searchSort==='price-high'?b.numPrice-a.numPrice:b.createdAt-a.createdAt);}
function itemResults(list){return list.length?`<div class="card-grid">${list.map(photoCard).join('')}</div>`:empty('Nenhum anúncio com esses filtros','Tente outro bairro ou amplie a faixa de preço.','search_off','clear-filters','Limpar filtros');}
